def protect(app,authenticate,authorize,allowed_origin):
    def application(environ,start_response):
        origin=environ.get('HTTP_ORIGIN','');trusted=origin==allowed_origin
        def send(status,headers,exc_info=None):
            clean=[(key,value) for key,value in headers if key.lower() not in ('access-control-allow-origin','access-control-allow-credentials','access-control-allow-methods','access-control-allow-headers','vary')]
            vary=[]
            for key,value in headers:
                if key.lower()=='vary':
                    for name in value.split(','):
                        name=name.strip()
                        if name and name.lower() not in {v.lower() for v in vary}:vary.append(name)
            if 'origin' not in {v.lower() for v in vary}:vary.append('Origin')
            clean.append(('Vary','*' if '*' in vary else ', '.join(vary)))
            if trusted:
                clean.extend([('Access-Control-Allow-Origin',allowed_origin),('Access-Control-Allow-Credentials','true')])
                if environ['REQUEST_METHOD']=='OPTIONS':clean.extend([('Access-Control-Allow-Methods','GET'),('Access-Control-Allow-Headers','Authorization')])
            return start_response(status,clean,exc_info)
        def reject(status,text,extra=()):
            body=text.encode();send(status,[('Content-Type','text/plain'),('Content-Length',str(len(body))),*extra]);return [body]
        if environ['REQUEST_METHOD']=='OPTIONS':send('204 No Content',[('Content-Length','0')]);return [b'']
        if environ['REQUEST_METHOD']!='GET':return reject('405 Method Not Allowed','method rejected')
        header=environ.get('HTTP_AUTHORIZATION','')
        token=header[7:] if header.startswith('Bearer ') else ''
        identity=authenticate(token)
        if identity is None:return reject('401 Unauthorized','authentication required',[('WWW-Authenticate','Bearer')])
        if not authorize(identity,environ['PATH_INFO']):return reject('403 Forbidden','read forbidden')
        scoped=dict(environ);scoped['opsforge.identity']=identity
        return app(scoped,send)
    return application
```

原题知识说明：
CORS主要控制浏览器是否允许脚本读取跨源响应，不是用户身份或对象权限机制；非浏览器客户端不受相同约束。服务端仍需认证和资源授权，凭据请求的来源匹配也要准确。测试未授权客户端直接请求应被拒绝，而不是依赖浏览器报错。
CORS决定浏览器脚本是否可以读取跨源响应，不保证请求没有发出；CSRF防护需独立验证令牌、来源和Cookie策略，二者不能互相替代。

